    }

    return time;
}

public List<List<Integer>> permute(int[] nums) {
        // Initialize the result list to hold all permutations
        List<List<Integer>> result = new ArrayList<>();
        // Recursively generate permutations
        permuteRecursive(nums, new ArrayList<>(), result);
        return result;
    }

private void permuteRecursive(int[] nums, List<Integer> current, List<List<Integer>> result) {
        // Base case: if the current list is the same size as the input nums
        if (current.size() == nums.length) {
            result.add(new ArrayList<>(current)); // Add a deep copy of the current list to the result
            return;
        }
        // Iterate through each number in the input nums array
        for (int i = 0; i < nums.length; i++) {
            // Skip duplicates by ensuring the number is not already in the current list
            if (!current.contains(nums[i])) {
                // Add the current number to the current list
                current.add(nums[i]);
                // Recursively generate permutations with the Remaining elements
                permuteRecursive(nums, current, result);
                // Remove the last added number from the current list to backtrack
                current.remove(current.size() - 1);
            }
        }
    }

