public static int countOilDeposits(char[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                if (isOilDeposit(grid, i, j)) {
                    count++;
                }
            }
        }
    }

    return count;
}

private static boolean isOilDeposit(char[][] grid, int row, int col) {
    // Check top neighbor
    if (row > 0 && grid[row - 1][col] == '@') return false;
    // Check bottom neighbor
    if (row < grid.length - 1 && grid[row + 1][col] == '@') return false;
    // Check left neighbor
    if (col > 0 && grid[row][col - 1] == '@') return false;
    // Check right neighbor
    if (col < grid[0].length - 1 && grid[row][col + 1] == '@') return false;

    return true;
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    boolean[][] visited = new boolean[grid.length][grid[0].length];
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (!visited[i][j] && grid[i][j] == '@') {
                count++;
                dfs(i, j, grid, visited);
            }
        }
    }
    return count;
}

private static void dfs(int row, int col, char[][] grid, boolean[][] visited) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || visited[row][col] || grid[row][col] != '@') {
        return;
    }
    visited[row][col] = true;
    dfs(row - 1, col, grid, visited); // Up
    dfs(row + 1, col, grid, visited); // Down
    dfs(row, col - 1, grid, visited); // Left
    dfs(row, col + 1, grid, visited); // Right
}

