private static String dfs(int n, int x, int y, int[][] paths, boolean[] visited) {
    // If the current position is the ending position, return "can be travelled"
    if (x == y) {
        return "can be travelled";
    }

    // Explore all possible directions
    for (int[] move : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
        int newX = x + move[0];
        int newY = y + move[1];
        // Check if the new position is within the bounds of the n-teresting space
        if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
            // Mark the new position as visited
            visited[newX][newY] = true;
            // Recursively explore the new position
            String result = dfs(n, newX, newY, paths, visited);
            // If travel is possible from the new position, return the result
            if (result.equals("can be travelled")) {
                return result;
            }
        }
    }

    // If no valid path is found from the current position, return "cannot be travelled"
    return "cannot be travelled";
}

