                return "can be travelled";
            }

            for (int[] path : paths) {
                if (path[0] == current[0] && path[1] == current[1]) {
                    int[] next = {current[0] + path[2], current[1] + path[3]};
                    if (!visited.contains(next)) {
                        queue.add(next);
                        visited.add(next);
                    }
                }
            }
        }

        return "cannot be travelled";
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    Set<Integer> visited = new HashSet<>();
    Queue<Integer> queue = new LinkedList<>();
    visited.add(start[0]);
    queue.offer(start[0]);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int i = 0; i < paths[current].length; i++) {
            int next = paths[current][i];
            if (!visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
        }
    }
    return "cannot be travelled";
}

