public static String appx(String word1, String word2) {
    int unionCount = 0;
    int intersectionCount = 0;

    for (int i = 0; i < word1.length(); i++) {
        char c1 = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            char c2 = word2.charAt(j);
            if (c1 == c2) {
                intersectionCount++;
            }
            unionCount++;
        }
    }

    if (unionCount == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = 1;
    for (int i = 1; i <= Math.min(intersectionCount, unionCount); i++) {
        if (intersectionCount % i == 0 && unionCount % i == 0) {
            gcd = i;
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + intersectionCount + "/" + unionCount + " = " + intersectionCount / gcd + "/" + unionCount / gcd;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Both words must be non-empty.");
    }

    int commonCharCount = 0;
    for (int i = 0; i < word1.length() && i < word2.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonCharCount++;
        }
    }

    int numerator = commonCharCount;
    int denominator = word1.length() + word2.length() - commonCharCount;

    if (denominator == 0) {
        return "Infinity";
    }

    long gcd = gcd(Math.abs(numerator), denominator);
    return "appx(" + word1 + ", " + word2 + ") = " + numerator / gcd + "/" + denominator / gcd;
}

private static long gcd(long a, long b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

