public static String appx(String word1, String word2) {
        Stack<Character> stack1 = new Stack<>();
        Stack<Character> stack2 = new Stack<>();
        int count = 0;

        for (char c : word1.toCharArray()) {
            if (!stack1.isEmpty()) {
                if (stack1.peek() == c) {
                    stack1.pop();
                    count++;
                } else {
                    stack1.push(c);
                }
            } else {
                stack1.push(c);
            }
        }

        for (char c : word2.toCharArray()) {
            if (!stack2.isEmpty()) {
                if (stack2.peek() == c) {
                    stack2.pop();
                    count++;
                } else {
                    stack2.push(c);
                }
            } else {
                stack2.push(c);
            }
        }

        BigInteger numerator = new BigInteger(count.toString());
        BigInteger denominator = new BigInteger(String.valueOf((word1.length() + word2.length()) * (word1.length() + word2.length())));
        BigInteger gcd = numerator.gcd(denominator);
        numerator = numerator.divide(gcd);
        denominator = denominator.divide(gcd);

        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }

