public boolean canArrange(int[] arr, int k) {
    Map<Integer, Integer> remainderMap = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        if (!remainderMap.containsKey(remainder)) {
            remainderMap.put(remainder, 0);
        }
        int complement = k - remainder;
        if (complement == 0 || remainderMap.containsKey(complement)) {
            return true;
        }
        remainderMap.put(remainder, remainderMap.get(remainder) + 1);
    }
    return false;
}

public boolean canArrange(int[] arr, int k) {
    int[] count = new int[k];
    for (int num : arr) {
        count[num % k]++;
    }
    for (int i = 1; i < k; i++) {
        if (count[i] != count[k - i]) {
            return false;
        }
    }
    return count[0] % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
