        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int[] remainderCounts = new int[k];

    // Count the remainders of each element in the array
    for (int num : arr) {
        remainderCounts[num % k]++;
    }

    // Check pairs for each possible remainder
    for (int i = 0; i < k; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false;
        }
    }

    // If all remainders are balanced, it's possible to form the pairs
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int[] remainderCount = new int[k];
    for (int num : arr) {
        remainderCount[num % k]++;
    }
    boolean valid = true;
    for (int remainder = 0; remainder < k; remainder++) {
        if ((remainder + 1) % 2 == 0 && remainderCount[remainder] % 2 != 0) {
            valid = false;
            break;
        } else if (remainder % 2 == 0 && remainderCount[remainder] % 2 == 0) {
            continue;
        } else {
            if (remainder == 0 || remainder == k - 1) {
                if (remainderCount[remainder] > 1) {
                    valid = false;
                    break;
                }
            } else if (remainderCount[remainder] % 2 != 0) {
                valid = false;
                break;
            }
        }
    }
    return valid;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph.putIfAbsent(u, new ArrayList<>()).add(v);
            graph.putIfAbsent(v, new ArrayList<>()).add(u);
        }

        Map<Integer, Integer> parentMap = new HashMap<>();
        parentMap.put(0, 0);

        Stack<Integer> stack = new Stack<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int node = stack.pop();
            for (int child : graph.getOrDefault(node, Collections.emptyList())) {
                if (parentMap.getOrDefault(child, -1) == -1) {
                    stack.push(child);
                    parentMap.put(child, node);
                }
            }
        }

        int ans = 0;
        for (int node = 0; node < n; node++) {
            int parent = parentMap.get(node);
            if (parent != -1) {
                ans += (hasApple[node] && !hasApple[parent]) + (hasApple[node] || hasApple[parent]);
            }
        }

        return ans;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    int time = 0;
    visited = new boolean[n];
    dfs(0);
    return time;
}

private int dfs(int u) {
    visited[u] = true;
    boolean hasChildApples = false;
    for (int v : graph.get(u)) {
        if (!visited[v]) {
            int childTime = dfs(v);
            if (childTime > 0 || hasApple[v]) {
                time += childTime + 2;
                hasChildApples = true;
            }
        }
    }
    return hasChildApples;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> tree = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tree.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }

        int time = dfs(tree, hasApple, 0, -1);
        return time == 0 ? 0 : time - 2; // Subtract 2 to exclude the edge back to the root
    }

private int dfs(List<List<Integer>> tree, boolean[] hasApple, int node, int parent) {
        int time = 0;
        for (int child : tree.get(node)) {
            if (child != parent) {
                int subTreeTime = dfs(tree, hasApple, child, node);
                if (subTreeTime > 0 || hasApple[child]) {
                    time += subTreeTime + (parent != -1);
                }
            }
        }
        return time;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Create a graph where each node is a key with its adjacent nodes
        ArrayList<List<Integer>> graph = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        // Perform a depth-first search (DFS) to count the time spent on collecting apples
        return countTime(0, -1, graph, hasApple);
    }

private int countTime(int currentNode, int parent, ArrayList<List<Integer>> graph, boolean[] hasApple) {
        int[] timeSpentByChildrens = new int[graph.get(currentNode).size()];
        int timeSpentOnApples = 0;
        for (int i = 0; i < graph.get(currentNode).size(); i++) {
            int child = graph.get(currentNode).get(i);
            if (child == parent) {
                continue;
            }
            // Calculate the time spent on collecting apples for the child
            int timeSpent = countTime(child, currentNode, graph, hasApple);
            // If the child has fruits or the time spent is positive (i.e., child collected apples), add to the total time
            if (hasApple[child] || timeSpent > 0) {
                timeSpentOnApples += timeSpent + 2; // 2 for parent to child path
                // If there is another child, need to add time for returning from that child to the parent
                if (i + 1 < graph.get(currentNode).size()) {
                    int timeToParentFromChild = countTime(graph.get(currentNode).get(i + 1), currentNode, graph, hasApple);
                    timeSpentOnApples += timeToParentFromChild;
                }
            }
        }
        return timeSpentOnApples;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Set<Integer> visited = new HashSet<>();
        Set<Integer> seen = new HashSet<>();
        // Build the adjacency list from the edges
        List<List<Integer>> adjacencyList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjacencyList.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adjacencyList.get(edge[0]).add(edge[1]);
            adjacencyList.get(edge[1]).add(edge[0]);
        }

        return dfsN(0, adjacencyList, hasApple, visited, seen);
    }

private int dfsN(int node, List<List<Integer>> adjList, boolean[] hasApple, Set<Integer> visited, Set<Integer> seen) {
        if (visited.contains(node)) {
            return 0;
        }
        visited.add(node);
        seen.add(node);
        int time = 0;
        for (int neighbor : adjList.get(node)) {
            time += dfsN(neighbor, adjList, hasApple, visited, seen);
            if (hasApple[neighbor] || seen.contains(neighbor)) {
                time += 2;
            }
        }
        return time;
    }

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }
    StringBuilder result = new StringBuilder();
    int[] count = new int[128]; // Assuming ASCII characters

    // Count the occurrence of each character
    for (char c : s.toCharArray()) {
        count[c]++;
    }

    // Extract characters based on the algorithm description
    int i = 0;
    while (i < count.length) {
        // Append the smallest non-repeating character
        while (i < count.length && count[i] == 0) {
            i++;
        }
        if (i < count.length) {
            result.append((char) i);
            count[i]--;
        }
        // Append the largest non-repeating character
        while (i < count.length && count[i] == 0) {
            i++;
        }
        if (i < count.length) {
            result.append((char) i);
            count[i]--;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    s = s.toLowerCase();
    int[] counts = new int[26];

    // Count occurrences of each character
    for (char c : s.toCharArray()) {
        counts[c - 'a']++;
    }

    int i = 0;
    while (i < s.length()) {
        // Add characters with the smallest value
        if (counts[i] > 0) {
            result.append((char) ('a' + i));
            counts[i]--;
        }
        i++;

        // Add characters with the largest value
        if (counts[25 - i] > 0) {
            result.append((char) ('a' + 25 - i));
            counts[25 - i]--;
        }
        i++;
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    // Populate the heaps with characters from the string
    for (int i = 0; i < s.length(); i++) {
        minHeap.offer(s.charAt(i));
        maxHeap.offer(s.charAt(i));
    }

    while (minHeap.size() > 0) {
        char minChar = minHeap.poll();
        result.append(minChar);

        if (minHeap.size() > 1 && minChar < maxHeap.peek()) {
            minChar = minHeap.poll();
            result.append(minChar);
        }

        while (maxHeap.size() > 1 && maxChar > minHeap.peek()) {
            maxChar = maxHeap.poll();
            result.append(maxChar);
        }
    }

    while (maxHeap.size() > 0) {
        char maxChar = maxHeap.poll();
        result.append(maxChar);
    }

    return result.toString();
}

public String sortString(String s) {
        StringBuilder result = new StringBuilder();
        char[] charArray = s.toCharArray();
        int[] count = new int[26]; // Array to count occurrences of characters
        int len = charArray.length;

        // Count occurrences of each character
        for (char c : charArray) {
            count[c - 'a']++;
        }

        int i = 0, j = len - 1;
        while (i < j) {
            // Pick the smallest character
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
            }
            // Pick the largest character
            if (count[j] > 0) {
                result.append((char) ('a' + j));
                count[j]--;
            }
        }

        // Pick the remaining character
        for (int k = 0; k < 26; k++) {
            while (count[k] > 0) {
                result.append((char) ('a' + k));
                count[k]--;
            }
        }

        return result.toString();
    }

public String sortString(String s) {
    int[] charCount = new int[26];
    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

    // Count the frequency of each character
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    // Add characters to the heaps
    for (int i = 0; i < 26; i++) {
        if (charCount[i] > 0) {
            minHeap.add((char) ('a' + i));
            maxHeap.add((char) ('a' + i));
        }
    }

    // Perform the sorting algorithm
    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
            result.append(minHeap.poll());
        }
        if (!minHeap.isEmpty() && minHeap.peek() != maxHeap.peek()) {
            result.append(minHeap.poll());
        }
        if (!maxHeap.isEmpty()) {
            result.append(maxHeap.poll());
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = Arrays.stream(nums).sum();
    int totalLength = nums.length;

    // Early return for scenarios that cannot be split evenly
    if (totalSum % totalLength != 0) {
        return false;
    }

    int targetAverage = totalSum / totalLength;

    // Calculate sum of subarrays that should be equal to the target average
    int requiredSum = targetAverage * (totalLength / 2);

    int leftSum = 0;
    for (int i = 0; i < totalLength; i++) {
        leftSum += nums[i];
        if (leftSum == requiredSum) {
            // Check the remaining part of the array
            return splitArraySameAverage(nums, i + 1);
        }
    }

    // If no such split is found, return false
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int length = nums.length;
    if (length < 2) return true; // An array with < 2 elements cannot be split into two non-empty arrays with the same average

    int totalSum = Arrays.stream(nums).sum();
    if (totalSum % length != 0) return false; // If the total sum is not divisible by the length, it's not possible to split it into two equal averages

    int target = totalSum / length;

    for (int i = 1; i < length; ++i) {
        if (sum(nums, 0, i - 1) == target && sum(nums, i, length - 1) == target) {
            return true;
        }
    }

    return false;
}

private int sum(int[] nums, int start, int end) {
    int sum = 0;
    for (int i = start; i <= end; ++i) {
        sum += nums[i];
    }
    return sum;
}

public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        if (totalSum % 2 != 0) {
            return false;
        }
        int targetAverage = totalSum / 2;
        int sum = 0;
        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            if (sum >= targetAverage) {
                if (sum == 2 * targetAverage || (sum - nums[i]) == 2 * targetAverage) {
                    return true;
                }
                sum -= nums[i];
            }
        }
        return false;
    }

public boolean splitArraySameAverage(int[] nums) {
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    if (totalSum % 2 != 0) {
        return false;
    }

    long targetSum = totalSum / 2;
    int n = nums.length;

    boolean[] dp = new boolean[targetSum + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int i = targetSum; i >= num; i--) {
            dp[i] = dp[i] || dp[i - num];
        }
    }

    return dp[targetSum];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) return 0;
    if (cost.length == 1) return cost[0];

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[1] = cost[0];
    dp[2] = cost[1];

    for (int i = 3; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    return dp[n];
}

