        if (!s.contains(cur)) return false;
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    // Check if the size of s is less than k
    if (s.length() < k) return false;

    HashSet<String> set = new HashSet<>();
    StringBuilder sb = new StringBuilder(s.substring(0, k));
    set.add(sb.toString());

    for (int i = k; i < s.length(); i++) {
        // Remove the first character and add the next character to the substring
        sb.setLength(sb.length() - 1);
        sb.append(s.charAt(i));
        if (set.contains(sb.toString())) return false;
        set.add(sb.toString());
    }

    // If all binary strings of length k are found, return true
    return true;
}

public boolean hasAllCodes(String s, int k) {
    cleanA(s, s.length() - k + 1);
    return s.length() == 2 << k;
}

private void cleanA(String s, int partition) {
    int len = s.length();
    for (int i = 0; i < len - partition + 1; i++) {
        char[] arr0 = s.substring(i, i + partition).toCharArray();
        Arrays.sort(arr0);
        if (arr0.length == 1) return;
        char[] arr = new char[arr0.length - 1];
        for (int j = 0; j < arr.length; j++) {
            arr[j] = arr0[j+1];
        }
        s = s.substring(0, i) + new String(arr) + s.substring(i + partition);
    }

}

