public int minInsertions(String s) {
        int left = 0;
        int insertions = 0;
        Deque<Character> stack = new LinkedList<>();

        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(c);
            } else {
                if (!stack.isEmpty()) {
                    stack.pop();
                } else {
                    insertions++;
                }
            }
        }

        insertions += stack.size();
        return insertions;
    }

