    for (int i = 0; i <= n / 2; i++) {
        count += n - (4 * i + 1);
    }
    return count;
}

public int minOperations(int n) {
    int count = 0;
    if (n % 2 == 0) {
        // If n is even, the middle element is minimized by making the last half of the array equal to 1.
        // There are (n / 2 - 1) pairs of elements to adjust, each taking 2 operations.
        count += (n / 2 - 1) * 2;
    } else {
        // If n is odd, the middle element is minimized by making half of the array equal to 1.
        // There are (n / 2) pairs of elements to adjust, each taking 2 operations.
        count += (n / 2) * 2;
    }
    return count;
}

public int minOperations(int n) {
    int totalSum = 0;
    for (int i = 0; i < n; i++) {
        totalSum += (2 * i) + 1;
    }
    int targetSum = totalSum % n;
    int requiredSum = totalSum / n * n;
    int operations = requiredSum - targetSum;
    return operations;
}

public int minOperations(int n) {
    int operations = 0;
    for (int i = 1; i <= n; i += 2) {
        // Calculate operations needed to make the current element equal to the nearest neighbor
        operations += Math.abs((i + 1) - ((i + 2) / 2));
    }
    return operations;
}

