public int maxAbsoluteSum(int[] nums) {
    int negativeMinSum = 0;
    int positiveMaxSum = 0;

    int minSum = 0;
    int maxSum = 0;

    for (int num : nums) {
        minSum = Math.min(minSum + num, num);
        negativeMinSum = Math.min(negativeMinSum, minSum);

        maxSum = Math.max(maxSum + num, num);
        positiveMaxSum = Math.max(positiveMaxSum, maxSum);
    }

    return Math.max(Math.abs(negativeMinSum), Math.abs(positiveMaxSum));
}

