    for (int num : nums) {
        if (num >= 0) {
            positiveSubarray[nums.length - 1] = Math.max(positiveSubarray[nums.length - 1], num);
            maxPositiveSubarray = Math.max(maxPositiveSubarray, positiveSubarray[nums.length - 1]);
        } else {
            negativeSubarray[nums.length - 1] = Math.max(negativeSubarray[nums.length - 1], num);
            maxNegativeSubarray = Math.max(maxNegativeSubarray, negativeSubarray[nums.length - 1]);
