public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    Set<String> uniqueSubsets = new HashSet<>();
    recurse(s, uniqueSubsets, "");
    return uniqueSubsets.size();
}

private void recurse(String s, Set<String> uniqueSubsets, String currentSubset) {
    if (s.isEmpty()) {
        uniqueSubsets.add(currentSubset);
        return;
    }

    for (int i = 1; i <= s.length(); i++) {
        String substring = s.substring(0, i);
        if (uniqueSubsets.contains(substring) || "".equals(substring)) {
            // Skip concatenating with existing subset to avoid duplicates (since substrings are not necessarily unique)
        } else {
            recurse(s.substring(i), uniqueSubsets, currentSubset + substring);
        }
    }
}

public int maxUniqueSplit(String s) {
    HashSet<String> uniqueSubstrings = new HashSet<>();
    for (int i = 0; i < s.length(); i++) {
        String currentSubstring = s.substring(0, i + 1);
        if (!uniqueSubstrings.contains(currentSubstring)) {
            uniqueSubstrings.add(currentSubstring);
            int remainingSubstringLength = s.length() - i - 1;
            if (remainingSubstringLength > 0) {
                uniqueSubstrings.add(s.substring(i + 1));
            }
        }
    }
    return uniqueSubstrings.size();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n <= 1) return n;

    int maxUnique = 0;
    List<Character> used = new ArrayList<>();

    for (int i = n - 1; i >= 0; i--) {
        used.add(s.charAt(i));
        if (!isDuplicate(String.valueOf(used))) {
            maxUnique++;
        }
        used.remove(used.size() - 1);
    }

    return maxUnique;
}

private boolean isDuplicate(String str) {
    Set<Character> set = new HashSet<>();
    for (char c : str.toCharArray()) {
        if (set.contains(c)) {
            return true;
        }
        set.add(c);
    }
    return false;
}

public int maxUniqueSplit(String s) {
    int maxCount = 0;
    for (int i = 0; i < s.length(); i++) {
        HashSet<String> uniqueSubstrings = new HashSet<>();
        while (i < s.length() && !uniqueSubstrings.contains(s.substring(i))) {
            uniqueSubstrings.add(s.substring(i));
            i++;
        }
        maxCount++;
    }
    return maxCount;
}

public int maxUniqueSplit(String s) {
    if (s.length() == 0) {
        return 0;
    }

    boolean[] visited = new boolean[26];
    int count = 0, j = 0;

    for (int i = 0; i < s.length(); i++) {
        while (j < s.length() && !visited[s.charAt(j) - 'a']) {
            visited[s.charAt(j) - 'a'] = true;
            j++;
        }

        count++;
        visited[s.charAt(j - 1) - 'a'] = false;
    }

    return count;
}

