public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder(n);
    while (k > 0) {
        int currentDigit = k % 26;
        if (currentDigit == 0) {
            result.append('z');
            k -= 26;
        } else {
            result.append((char) ('a' + currentDigit));
            k -= currentDigit;
        }
    }
    return result.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder str = new StringBuilder(n);
    int index = 0;
    char currentChar = 'a';

    while (k > 0) {
        if (index < n && str.charAt(index) == currentChar) {
            k -= n;
            index++;
            currentChar = nextChar(currentChar);
        } else {
            k--;
            index++;
        }
    }

    return str.toString();
}

private char nextChar(char c) {
    char next = c + 1;
    if (next > 'z') {
        next = 'a';
    }
    return next;
}

