private String getSmallestString(int n, int k, int[] alphabet) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n - 1; i++) {
        sb.append(alphabet[i]);
        k -= i + 1;
    }
    sb.append(alphabet[n - 1]);
    k -= alphabet.length - 1;
    if (k > 0) {
        sb.append(alphabet[n - 1] - k);
        k = 0;
    } else {
        String res = sb.toString();
        sb.reverse();
        return res;
    }
    return sb.toString().concat(new StringBuilder().reverse().toString());
}

public String getSmallestString(int n, int k) {
    String result = "";
    char[] charArray = new char[n];

    // Start from the highest possible character (z) to Decrease the number of characters
    for (int i = 25; i >= 0; i--) {
        charArray[n - i - 1] = (char) ('a' + i);
        k -= i + 1;

        // If k becomes zero or negative, no more characters are necessary
        if (k <= 0) {
            break;
        }
    }

    result = new String(charArray);

    return result;
}

