public static double calculateProbability(int n) {
    if (n <= 2) {
        return 1.0; // Only two people, the last one will definitely sit in their own seat
    }
    double probability = 1.0;
    for (int i = 2; i < n; i++) {
        double division = (i + 1) / i;
        if (i == n - 1) {
            division = 1.0; // If the last person picks a different seat, calculate the probability
        }
        probability *= (1 - division);
    }
