public static double calculateProbability(int n) {
    if (n == 1) {
        return 1.0;
    }
    double totalWays = n * (n - 1);
    double favorableWays = 0;
    for (int i = 2; i <= n - 1; i++) {
        if (i == n) {
            favorableWays++;
        } else {
            favorableWays += n - i;
        }
    }
    return favorableWays / totalWays;
}

