public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false; // The only numbers less than or equal to 0 are not powers of two
    }

    // Check if the number is a power of two by repeatedly dividing by 2 until it is no longer divisible
    while (n != 1) {
        if (n % 2 != 0) {
            return false; // A number is not a power of two if it has a remainder of 1
        }
        n /= 2;
    }

    return true; // If the while loop completes without returning false, n is a power of two
}

