public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Check for horizontal lines
    for (int i = 0; i < m; i++) {
        int currentLength = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                currentLength = 0;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    // Check for vertical lines
    for (int j = 0; j < n; j++) {
        int currentLength = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                currentLength = 0;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    // Check for diagonal lines
    for (int i = 0; i < m; i++) {
        int currentLength = 0;
        for (int j = 0; j < n; j++) {
            if (i - j >= 0 && mat[i][j] == 1) {
                currentLength++;
            } else {
                currentLength = 0;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    // Check for antidiagonal lines
    for (int i = 0; i < m; i++) {
        int currentLength = 0;
        for (int j = 0; j < n; j++) {
            if (i + j < n && mat[i][j] == 1) {
                currentLength++;
            } else {
                currentLength = 0;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    return maxLength;
}

