    int[][] directions = new int[][]{{0, 1}, {1, 0}, {1, 1}, {1, -1}};

    int maxLength = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                for (int[] direction : directions) {
                    int count = 1;
                    int x = i + direction[0];
                    int y = j + direction[1];

                    while (x < rows && y < cols && mat[x][y] == 1) {
                        count++;
                        x += direction[0];
                        y += direction[1];
                    }

                    maxLength = Math.max(maxLength, count);
                }
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
        int maxLength = 0;
        if (mat == null || mat.length == 0) {
            return maxLength;
        }

        int rows = mat.length;
        int cols = mat[0].length;

        // Create DP arrays for horizontally and vertically consecutive 1s
        int[][] dpHor = new int[rows][cols];
        int[][] dpVer = new int[rows][cols];

        // For each cell, check and update the DP arrays
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (mat[i][j] == 1) {
                    if (i == 0) {
                        dpHor[i][j] = 1;
                    } else if (j == 0) {
                        dpVer[i][j] = 1;
                    } else {
                        dpHor[i][j] = dpHor[i - 1][j] + 1;
                        dpVer[i][j] = dpVer[i][j - 1] + 1;
                    }
                    maxLength = Math.max(maxLength, dpHor[i][j]);
                    maxLength = Math.max(maxLength, dpVer[i][j]);
                }
            }
        }

        return maxLength;
    }

public static int longestLine(int[][] mat) {
