    }

    int rows = mat.length;
    int cols = mat[0].length;

    int[] vertical[] = new int[rows];
    int[] horizontal[] = new int[cols];
    int[] diagonal[] = new int[Math.min(rows, cols)];
    int[] antiDiagonal[] = new int[Math.min(rows, cols)];

    int maxLen = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                vertical[i] = (j == 0) ? 1 : (vertical[i - 1] + 1);
                horizontal[j] = (i == 0) ? 1 : (horizontal[j - 1] + 1);
                diagonal[i] = (i == 0 || j == 0) ? 1 : (diagonal[i - 1] + 1);
                antiDiagonal[i + j] = (i == 0 || j == cols - 1) ? 1 : (antiDiagonal[i - 1] + 1);

                maxLen = Math.max(maxLen, vertical[i], horizontal[j], diagonal[i], antiDiagonal[i + j]);
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    StringBuilder sb = new StringBuilder();
    if (n == 0) {
        return "0";
    }
    while (n > 0) {
        int digit = n % 10;
        if (sb.length() > 0 && sb.charAt(sb.length() - 1) != '.') {
            sb.insert(0, '.');
        }
        sb.insert(0, digit);
        n /= 10;
        if (n > 0 && sb.length() < 4) {
            sb.insert(2, '.');
            sb.insert(0, '0');
        }
    }
    return sb.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    String reversedStr = new StringBuilder(n).reverse().toString();
    StringBuilder result = new StringBuilder();

    int groups = 0;
    for (char c : reversedStr.toCharArray()) {
        result.append(c);
        groups++;

        if (groups % 3 == 0 && groups < reversedStr.length()) {
            result.append(".");
        }
    }

    return result.reverse().toString();
}

