        }
        return sb.toString();
    }

public static String addThousandSeparator(int n) {
    String numStr = Integer.toString(n);
    StringBuilder result = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        result.insert(0, numStr.charAt(i));
        count++;
        if (count == 3) {
            result.insert(0, '.');
            count = 0;
        }
    }
    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder sb = new StringBuilder();
    int digitCount = 0;

    while (n > 0) {
        int digit = n % 10;
        sb.append(digit);
        digitCount++;

        if (digitCount % 3 == 0 && n != 0) {
            sb.append('.');
        }

        n /= 10;
    }

    if (sb.length() > 0 && sb.charAt(sb.length() - 1) == '.') {
        sb.deleteCharAt(sb.length() - 1);
    }

    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A.length <= 0) {
        return 0;
    }

    // Sort the array in ascending order
    Arrays.sort(A);

    // Generate square permutations recursively
    return generateSquarePermutations(A, 0);
}

private static int generateSquarePermutations(int[] A, int start) {
    int count = 0;

    // If all elements are sorted, check if it is a square array
    if (isSquareArray(A)) {
        count = 1;
    } else {
        for (int i = start; i < A.length - 1; i++) {
            // Swap the current element with the next element
            int temp = A[i];
            A[i] = A[i + 1];
            A[i + 1] = temp;

            // Continue generating permutations for the remaining elements
            count += generateSquarePermutations(A, i + 1);

            // Swap back to the original position
            temp = A[i];
            A[i] = A[i + 1];
            A[i + 1] = temp;
        }
    }

    return count;
}

private static boolean isSquareArray(int[] A) {
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (!isPerfectSquare(sum)) {
            return false;
        }
    }
    return true;
}

private static boolean isPerfectSquare(int n) {
    return (int)Math.round(Math.sqrt(n)) * (int)Math.round(Math.sqrt(n)) == n;
}

