public static int[] sortArray(int[] A) {
    int l = A.length;
    for (int i = 0; i < l - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < l; j++) {
            if (Math.abs(A[j] - pow(root(A[j]),2)) == 0) {
                minIndex = j;
                break;
            }
        }
        int temp = A[i];
        A[i] = A[minIndex];
        A[minIndex] = temp;
    }
    return A;
}

public static int root(int n) {
    int start = 0;
    int end = n;
    int res = 0;
    while(start<=end){
        int mid = (start+end)/2;
        if(mid*mid <= n){
            start = mid+1;
            res = mid;
        }
        else{
            end = mid-1;
        }
    }
    return res;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length < 2) {
        return 0;
    }

    int length = A.length;
    int[] squareArray = new int[length];
    for (int i = 0; i < length; i++) {
        int square = (int) Math.sqrt(A[i]);
        if (square * square == A[i]) {
            squareArray[i] = square;
        } else {
            return 0; // A[i] is not a perfect square
        }
    }

    return helper(squareArray, new boolean[length], new Map<Integer, Integer>());
}

private static int helper(int[] array, boolean[] used, Map<Integer, Integer> map) {
    if (used.length == 0) {
        return 1;
    }

    int result = 0;
    for (int i = 0; i < used.length; i++) {
        if (used[i]) {
            continue;
        }

        if (i > 0 && array[i - 1] == array[i] && !used[i - 1]) {
            continue;
        }

        used[i] = true;
        map.put(array[i], i);
        result += helper(array, used, map);
        map.remove(array[i]);
        used[i] = false;
    }

    return result;
}

public static int largestRectangleArea(int[] heights) {
    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;

    for (int i = 0; i <= heights.length; i++) {
        int height = (i == heights.length) ? 0 : heights[i];

        while (!stack.isEmpty() && height < heights[stack.peek()]) {
            int barHeight = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, barHeight * width);
        }

        stack.push(i);
    }

    return maxArea;
}

