public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] largestRightSmall = new int[n];
    int[] largestLeftSmall = new int[n];
    int maxArea = 0;

    // Fill largestRightSmall array with the nearest smaller element to the right
    Stack<Integer> stack = new Stack<>();
    largestRightSmall[n - 1] = n;
    stack.push(n - 1);

    for (int i = n - 2; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        largestRightSmall[i] = stack.isEmpty() ? n : stack.peek();
        stack.push(i);
    }

    // Fill largestLeftSmall array with the nearest smaller element to the left
    stack.clear();
    largestLeftSmall[0] = -1;
    stack.push(0);

    for (int i = 1; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        largestLeftSmall[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }

    // Calculate the area of each bar and update the maximum area if necessary
    for (int i = 0; i < n; i++) {
        int width = largestRightSmall[i] - largestLeftSmall[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int largestArea = 0;
    int width = 0;
    Stack<Integer> stack = new Stack<>();

    for(int i = 0; i < heights.length; i++) {
        while(!stack.isEmpty() && heights[i] < heights[stack.peek()]) {
            int index = stack.pop();
            int height = heights[index];
            width = stack.isEmpty() ? i : i - stack.peek() - 1;

            largestArea = Math.max(largestArea, height * width);
        }
        stack.push(i);
    }

    while(!stack.isEmpty()) {
        int index = stack.pop();
        int height = heights[index];
        width = stack.isEmpty() ? heights.length : heights.length - stack.peek() - 1;

        largestArea = Math.max(largestArea, height * width);
    }

    return largestArea;
}

