        }

        // Calculate maximum area using the left and right minimal heights and heights
        for (int i = 0; i < heights.length; i++) {
            int width = rightMin[i] - leftMin[i] - 1;
            int area = heights[i] * width;
            maxArea = Math.max(maxArea, area);
        }

        return maxArea;
    }

