public static int[] diagonalOrder(int[][] mat) {
    int[] diagElements = new int[mat.length * mat[0].length];
    int top = 0, left = 0;

    while (top < mat.length && left < mat[0].length) {
        if (left == 0) {
            while (top < mat.length)
                diagElements[top++] = mat[top][left++];
        } else if (top == mat.length - 1) {
            while (left < mat[0].length)
                diagElements[top++] = mat[top][left++];
        } else {
            int temp = mat[top][left];
            while (left > 0 && top < mat.length)
                diagElements[++top][--left] = mat[top][left];
           (diagElements[top][left++] = temp);
        }
    }
    return diagElements;
