    int maxRow = mat.length;
    int maxCol = mat[0].length;
    int index = 0;
    int[] result = new int[maxRow * maxCol];

    for (int row = 0, col = 0, dirIndex = 0; row < maxRow && col < maxCol; row++) {
        result[index++] = mat[row][col];

        // Calculate next row and column based on current direction
        int nextRow = row + dir[dirIndex][0];
        int nextCol = col + dir[dirIndex][1];

        // Update direction if the current position is out of bounds
        if (nextRow < 0 || nextRow >= maxRow || nextCol < 0 || nextCol >= maxCol) {
            dirIndex = (dirIndex + 1) % 2;
            row += dir[dirIndex][0];
            col += dir[dirIndex][1];
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
        char[] digits = n + "";

        for (int i = digits.length - 1; i >= 0; i--) {
            for (int j = i - 1; j >= 0; j--) {
                if (digits[j] < digits[i]) {
                    // Swap the digits at positions i and j
                    char temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;

                    // Convert the reversed array of digits back to an integer
                    return Integer.parseInt(new String(digits));
                }
            }
        }

        // If no larger permutation is found, n can't be rearranged into a larger number
        return -1;
    }

public static int findSmallestInteger(int n) {
    if (n < 10) return -1;

    boolean[] digits = new boolean[10];
    while (n > 0) {
        digits[n % 10] = true;
        n /= 10;
    }

    for (int i = 9; i > 0; i--) {
        if (digits[i]) {
            int temp = n;
            int tempI = Collections.binarySearch(digits, true, 0, 10);
            while (temp >= 0 && digits[temp % 10] && temp >= i) {
                temp /= 10;
            }
            if (temp < 0) continue;

            digits[i] = false;
            int iI = Collections.binarySearch(digits, true, 0, 10);
            while (iI >= 0 && digits[iI] == true && iI < i) {
                iI--;
            }
            char tempc = iI >= 0 ? Character.forDigit(iI, 10) : '0';
            for (int j = i + 1; j < 10; j++) {
                if (digits[j]) {
                    char c = j < i ? charForDigit(i, 10) : tempc;
                    temp = temp * 10 + c;
                    digits[j] = false;
                }
            }
            return temp;
        }
    }
    return -1;
}

public static int findSmallestInteger(int n) {
