        Arrays.sort(chars);

        for (int i = chars.length - 1; i >= 0; i--) {
            for (int j = i - 1; j >= 0; j--) {
                if (chars[i] - chars[j] > 0) {
                    char temp = chars[i];
                    chars[i] = chars[j];
                    chars[j] = temp;
                    break;
                }
            }
            if (chars[i] - chars[j] > 0) {
                int[] sortedArray = Arrays.copyOfRange(chars, 0, i + 1);
                int[] tempArray = Arrays.copyOfRange(chars, i + 1, chars.length);
                Arrays.sort(tempArray);
                char[] result = new char[chars.length];
                System.arraycopy(sortedArray, 0, result, 0, sortedArray.length);
                for (int k = 0; k < tempArray.length; k++) {
                    result[k + sortedArray.length] = tempArray[k];
                }
                return Integer.parseInt(String.valueOf(result));
            }
        }

        return -1;
    }

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int maxIndex = -1;

    // Find the largest index such that digits[i] is less than digits[i+1]
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            maxIndex = i;
            break;
        }
    }

    if (maxIndex == -1) {
        // If no such index exists, no possible rearrangement greater than n
        return -1;
    }

    // Find the smallest index such that digits[j] is greater than digits[maxIndex]
    int minIndex = -1;

    for (int j = digits.length - 1; j > maxIndex; j--) {
        if (digits[j] > digits[maxIndex]) {
            minIndex = j;
            break;
        }
    }

    // Swap digits[maxIndex] and digits[minIndex]
    char temp = digits[maxIndex];
    digits[maxIndex] = digits[minIndex];
    digits[minIndex] = temp;

    // Reverse the digits after index maxIndex
    for (int i = maxIndex + 1, j = digits.length - 1; i < j; i++, j--) {
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
    }

    // Convert the sorted array of digits back to a number
    return Integer.parseInt(new String(digits));
}

public static int findSmallestInteger(int n) {
    String numStr = Integer.toString(n);
    char[] digits = numStr.toCharArray();
    int i = numStr.length() - 2;

    // Find the first digit that is smaller than its next digit
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i == -1) {
        return -1; // If no such digit is found, return -1
    }

    int j = numStr.length() - 1;

    // Find the smallest digit greater than the found digit
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    swap(digits, i, j);

    // Sort the remaining digits in ascending order
    Arrays.sort(digits, i + 1);

    // Form the smallest rearranged integer
    return Integer.parseInt(new String(digits));
}

