private static void generateCenterSymmetric(StringBuilder sb, int start, List<String> results) {
        if (sb.length() == n) {
            results.add(sb.toString());
            return;
        }

        sb.append('0');
        generateCenterSymmetric(sb, start + 1, results);
        sb.deleteCharAt(sb.length() - 1);
        if (start == 0) {
            sb.append('1');
            generateCenterSymmetric(sb, start + 1, results);
            sb.deleteCharAt(sb.length() - 1);
        }
        sb.append('8');
        generateCenterSymmetric(sb, start + 1, results);
        sb.deleteCharAt(sb.length() - 1);
    }

