public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n % 2 == 0) {
        return result;
    }
    int start = n / 2 - 1;
    int end = n / 2 + 1;
    StringBuilder builder = new StringBuilder();

    for (int i = start; i <= end; i++) {
        int count = 2 * (n - i);
        if (i == start) {
            count--;
        } else if (i == end) {
            count--;
        }
        for (int j = 0; j < count; j++) {
            builder.append("0");
        }
        String str = builder.toString();
        String reversedStr = new StringBuilder(str).reverse().toString();
        result.add(str + reversedStr);
        builder.setLength(0);
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the points form a valid triangle (3 points)
    if (points.length != 3) {
        return false;
    }

    // Calculate the area of the triangle using the determinant method
    double area = (points[1][0] - points[0][0]) * (points[2][1] - points[0][1]) -
              (points[2][0] - points[0][0]) * (points[1][1] - points[0][1]);

    // A boomerang should have a non-zero area
    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
