    // Calculate the area of the triangle formed by the points
    int area = (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2;

    // A non-zero area indicates that the points form a boomerang
    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
