    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the cross product of vectors AB and AC
    int crossProduct = (x2 - x1) * (y3 - y2) - (y2 - y1) * (x3 - x2);

    // A boomerang has a non-zero cross product
    return crossProduct != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    Queue<Long> pq = new PriorityQueue<>();
    pq.offer(1L);
    Set<Long> seen = new HashSet<>();
    seen.add(1L);

    int[] uglyFactors = {2, 3, 5};
    int[] temp = new int[n];
    temp[0] = 1;
    for (int i = 1; i < n; i++) {
        long nextUgly = pq.poll();
        temp[i] = (int) nextUgly;

        for (int factor : uglyFactors) {
            long newUgly = nextUgly * factor;
            if (!seen.contains(newUgly)) {
                pq.offer(newUgly);
                seen.add(newUgly);
            }
        }
    }

    return temp[n - 1];
}

public static int findNthUglyNumber(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    if (n == 1) {
        return 1;
    }

    int[] dp = new int[n];
    dp[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(dp[index2] * 2, Math.min(dp[index3] * 3, dp[index5] * 5));
        dp[i] = nextUglyNumber;

        if (nextUglyNumber == dp[index2] * 2) {
            index2++;
        }
        if (nextUglyNumber == dp[index3] * 3) {
            index3++;
        }
        if (nextUglyNumber == dp[index5] * 5) {
            index5++;
        }
    }

    return dp[n - 1];
}

