public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    if (n == 1) {
        return 1;
    }

    int minHeap = new PriorityQueue<>();
    minHeap.offer(1);
    int[] primes = {2, 3, 5};
    Set<Integer> visitedNumbers = new HashSet<>();
    visitedNumbers.add(1);

    while (n > 1) {
        int currentUglyNumber = minHeap.poll();
        for (int prime : primes) {
            int nextUglyNumber = currentUglyNumber * prime;
            if (!visitedNumbers.contains(nextUglyNumber)) {
                visitedNumbers.add(nextUglyNumber);
                minHeap.offer(nextUglyNumber);
            }
        }
        n--;
    }
    return minHeap.poll();
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 1; // Any number multiplied by 0 or 1 is 0 or 1, respectively.

    int a = 0, b = 0, c = 0;
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[a] * 2, Math.min(uglyNumbers[b] * 3, uglyNumbers[c] * 5));
        uglyNumbers[i] = min;

        if (min == uglyNumbers[a] * 2) a++;
        if (min == uglyNumbers[b] * 3) b++;
        if (min == uglyNumbers[c] * 5) c++;
    }

    return uglyNumbers[n - 1];
}

