public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        for (int i = 1; i <= 9; i++) {
            result.add(i);
            if (i == n) {
                return result;
            }
        }
        for (int i = 10; i <= n; i *= 10) {
            for (int j = 0; j < 10; j++) {
                result.add(i + j);
                if (i + j == n) {
                    return result;
                }
            }
        }
        Collections.sort(result);
        return result;
    }

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }

        int current = 1;
        while (current <= n) {
            result.add(current);
            if (current * 10 <= n) {
                current *= 10;
            } else if (current % 10 < 9) {
                current++;
                while (current % 10 == current % 100) {
                    current++;
                }
            } else {
                current /= 10;
            }
        }

        return result;
    }

