        List<Integer> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        for (int i = 1; i <= 9; i++) {
            result.add(i);
            if (i <= n) {
                lexicalOrderWithRange(10 * i, n, result); // Recursively call for the upcoming levels
            }
        }
        return result;
    }

public static List<Integer> lexicalOrderWithRange(int num, int limit, List<Integer> result) {
        if (num > limit) {
            return result;
        }
        result.add(num);
        if (num % 10 < 9) { // Check if we can continue the sequence by appending 1
            lexicalOrderWithRange(num * 10 + 1, limit, result); // Recursively call for the upcoming levels
        }
        if (num % 10 > 0) { // Check if we can continue the sequence by appending 9
            lexicalOrderWithRange(num * 10 - 1, limit, result); // Recursively call for the upcoming levels
        }
        return result;
    }

